public class TextBuffer_getTextBuffer_TriageGen1Test {

    private BufferRecycler recycler;
    private TextBuffer textBuffer;

    @Before
    public void setUp() {
        recycler = new BufferRecycler();
        textBuffer = new TextBuffer(recycler);
    }

    @Test
    public void testGetTextBuffer_SharedInputBuffer() {
        char[] sharedBuf = {'a', 'b', 'c'};
        // resetWithShared sets _inputStart to a non-negative value
        textBuffer.resetWithShared(sharedBuf, 0, 3);

        char[] result = textBuffer.getTextBuffer();

        assertSame("Should return the shared input buffer", sharedBuf, result);
    }








}

package com.fasterxml.jackson.core.util;

import com.fasterxml.jackson.core.io.NumberInput;
import com.fasterxml.jackson.core.util.BufferRecycler;
import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.util.*;
import java.util.ArrayList;
import java.util.Arrays;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

public class TextBuffer_getTextBuffer_TriageGen1Test {

    private BufferRecycler recycler;
    private TextBuffer textBuffer;

    @Before
    public void setUp() {
        recycler = new BufferRecycler();
        textBuffer = new TextBuffer(recycler);
    }





    @Test
    public void testGetTextBuffer_ResultString() {
        // To reach this, _inputStart < 0, _resultArray == null, and _resultString != null.
        // resetWithString sets _resultString and sets _resultArray to null initially.
        textBuffer.resetWithString("hello");

        char[] result = textBuffer.getTextBuffer();

        assertNotNull(result);
        assertArrayEquals("hello".toCharArray(), result);

        // Second call should return the newly created _resultArray (cached)
        char[] result2 = textBuffer.getTextBuffer();
        assertSame("Should return the cached _resultArray on second call", result, result2);
    }




}

package com.fasterxml.jackson.core.util;

import com.fasterxml.jackson.core.io.NumberInput;
import com.fasterxml.jackson.core.util.BufferRecycler;
import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.util.*;
import java.util.ArrayList;
import java.util.Arrays;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

public class TextBuffer_getTextBuffer_TriageGen1Test {

    private BufferRecycler recycler;
    private TextBuffer textBuffer;

    @Before
    public void setUp() {
        recycler = new BufferRecycler();
        textBuffer = new TextBuffer(recycler);
    }







    @Test
    public void testGetTextBuffer_SingleSegment() {
        // To reach this, _inputStart < 0, _resultArray == null, _resultString == null, and _hasSegments == false.
        // A fresh TextBuffer or one reset with empty has _hasSegments = false.
        textBuffer.resetWithEmpty();

        char[] result = textBuffer.getTextBuffer();

        assertNotNull(result);
        // It should return the current segment (internal buffer)
        assertSame("Should return the current segment", textBuffer.getCurrentSegment(), result);
    }


}
